/// Represents a GPS coordinate snapshot reported by a vehicle.
class TelemetryLocation {
  /// Geographic latitude.
  final double latitude;

  /// Geographic longitude.
  final double longitude;

  /// Optional altitude in meters.
  final double? altitude;

  /// Optional heading in degrees.
  final double? heading;

  /// Creates a [TelemetryLocation].
  const TelemetryLocation({
    required this.latitude,
    required this.longitude,
    this.altitude,
    this.heading,
  });
}

/// Represents a Diagnostic Trouble Code (DTC) alert generated by telemetry.
class DtcAlert {
  /// The alert identifier.
  final String id;

  /// The vehicle identifier.
  final String vehicleId;

  /// The OBD2 fault code (e.g. `P0300`).
  final String dtcCode;

  /// Severity level (`LOW`, `WARNING`, `HIGH`, `CRITICAL`).
  final String severity;

  /// Optional short alert title.
  final String? title;

  /// Human-readable fault description.
  final String description;

  /// Timestamp when the alert was recorded.
  final DateTime? createdAt;

  /// Creates a [DtcAlert].
  const DtcAlert({
    required this.id,
    required this.vehicleId,
    required this.dtcCode,
    required this.severity,
    this.title,
    required this.description,
    this.createdAt,
  });
}

/// Represents a single OBD2 telemetry snapshot for a vehicle or device.
class TelemetrySnapshot {
  /// Optional snapshot identifier.
  final String? id;

  /// Optional registration identifier.
  final String? registrationId;

  /// Optional branch identifier.
  final String? branchId;

  /// Device identifier.
  final String? deviceId;

  /// Vehicle identifier.
  final String vehicleId;

  /// Engine speed in revolutions per minute.
  final int rpm;

  /// Coolant temperature in Celsius.
  final double coolantTempC;

  /// Vehicle speed in km/h.
  final double speedKmh;

  /// Odometer reading in km, if available.
  final double? odometerKm;

  /// Fuel level percentage (`0.0` to `100.0`).
  final double fuelLevelPercent;

  /// Battery voltage in volts, if available.
  final double? batteryVoltage;

  /// Snapshot timestamp.
  final DateTime timestamp;

  /// Creates a [TelemetrySnapshot].
  const TelemetrySnapshot({
    this.id,
    this.registrationId,
    this.branchId,
    this.deviceId,
    required this.vehicleId,
    required this.rpm,
    required this.coolantTempC,
    required this.speedKmh,
    this.odometerKm,
    required this.fuelLevelPercent,
    this.batteryVoltage,
    required this.timestamp,
  });
}

/// Represents the current health diagnostics summary of a vehicle.
class VehicleDiagnostics {
  /// The tenant identifier.
  final String tenantId;

  /// The vehicle identifier.
  final String vehicleId;

  /// Overall health status (`HEALTHY`, `WARNING`, `CRITICAL`).
  final String overallStatus;

  /// Timestamp of the latest telemetry reading.
  final DateTime? lastTimestamp;

  /// Last reported GPS location, if available.
  final TelemetryLocation? lastLocation;

  /// Latest vehicle speed in km/h.
  final double? lastSpeedKmh;

  /// Latest engine RPM.
  final int? lastEngineRpm;

  /// Latest coolant temperature in Celsius.
  final double? lastCoolantTempC;

  /// Latest battery voltage.
  final double? lastBatteryVoltage;

  /// Latest fuel level percentage.
  final double? lastFuelLevelPercent;

  /// Currently active DTC codes.
  final List<String> activeDtcs;

  /// Currently active DTC alerts.
  final List<DtcAlert> activeAlerts;

  /// Recently resolved or historical alerts.
  final List<DtcAlert> recentAlerts;

  /// Creates a [VehicleDiagnostics].
  const VehicleDiagnostics({
    required this.tenantId,
    required this.vehicleId,
    required this.overallStatus,
    this.lastTimestamp,
    this.lastLocation,
    this.lastSpeedKmh,
    this.lastEngineRpm,
    this.lastCoolantTempC,
    this.lastBatteryVoltage,
    this.lastFuelLevelPercent,
    this.activeDtcs = const [],
    this.activeAlerts = const [],
    this.recentAlerts = const [],
  });
}

/// Represents the runtime status of the IoT telemetry simulator.
class SimulatorStatus {
  /// Whether the simulator is currently running.
  final bool isRunning;

  /// Active simulation scenario name.
  final String? scenario;

  /// Emission mode (`STREAM` or `BATCH`).
  final String? emissionMode;

  /// Target branch identifier.
  final String? branchId;

  /// Total messages sent so far.
  final int totalSent;

  /// Total messages accepted.
  final int totalSuccess;

  /// Total messages failed.
  final int totalFailed;

  /// Current throughput in messages per second.
  final double currentThroughputMps;

  /// Last recorded error message, if any.
  final String? lastError;

  /// Creates a [SimulatorStatus].
  const SimulatorStatus({
    required this.isRunning,
    this.scenario,
    this.emissionMode,
    this.branchId,
    this.totalSent = 0,
    this.totalSuccess = 0,
    this.totalFailed = 0,
    this.currentThroughputMps = 0.0,
    this.lastError,
  });
}
